// LookupCatalogue finds a catalogue definition by token and optional package.
func LookupCatalogue(token string, pkg string) *CatalogueDefinition {
	var fallback *CatalogueDefinition
	for i := range AllCatalogueDefinitions {
		def := &AllCatalogueDefinitions[i]
		if def.Token == token {
			if pkg != "" && def.Package == pkg {
				return def
			}
			if fallback == nil {
				fallback = def
			}
		}
	}
	return fallback
}

// CatalogueEntries returns all canonical entries.
func CatalogueEntries() []CatalogueDefinition {
	out := make([]CatalogueDefinition, len(AllCatalogueDefinitions))
	copy(out, AllCatalogueDefinitions)
	return out
}
